    merged = []
    for interval in sorted(intervals, key=lambda item: (item[0], item[1])):
        start, end = interval
        if not merged or start > merged[-1][1]:
            merged.append((start, end))
        elif end > merged[-1][1]:
            merged[-1] = (merged[-1][0], end)
    return merged

